import { onAuthStateChanged, signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut, updateProfile } from 'https://www.gstatic.com/firebasejs/12.19.0/firebase-auth.js';
import { firebaseConfigured, auth } from './firebase.js';
import { subscribeStudents, subscribeFees, subscribeAttendance, saveAttendance, subscribeExpenses, addExpense, deleteExpense, addStudent, updateStudent, deleteStudent, createMissingMonthlyFees, updateFee, upsertUserProfile, getUserProfile } from './firebase-data.js';

const $ = id => document.getElementById(id);
const money = n => '₹' + Number(n || 0).toLocaleString('en-IN');
const monthName = value => value ? new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric'}).format(new Date(`${value}-01T00:00:00`)) : '';
const initialMonth = `${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}`;
const isoToday = () => new Date().toISOString().slice(0,10);
const pad2 = n => String(n).padStart(2,'0');
const DEFAULT_SETTINGS = {
  classes:['Class 6','Class 7','Class 8','Class 9','Class 10'],
  batches:['Morning','Evening','Weekend','Special Batch'],
  subjects:['English','Math','Science','SST'],
  dueDay:10
};
const state = {uid:null,user:null,students:[],fees:[],attendance:[],expenses:[],page:'home',editingId:null,payingId:null,profileId:null,idCardStudentId:null,settings:{...DEFAULT_SETTINGS},unsub:[],month:initialMonth,attendanceDate:isoToday(),attendanceReportMonth:initialMonth};

function initials(name=''){return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join('')||'S'}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function csvEscape(s){return `"${String(s??'').replace(/"/g,'""')}"`}
function cleanError(err){return (err?.message||'Something went wrong.').replace(/^Firebase:\s*/i,'')}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2200)}
let confirmResolver=null;
function closeAppConfirm(result){if(!confirmResolver)return;const resolve=confirmResolver;confirmResolver=null;$('confirmModal').classList.remove('show');$('confirmModal').setAttribute('aria-hidden','true');document.body.classList.remove('confirm-open');resolve(!!result)}
function appConfirm(message,{title='Confirm Action',confirmText='OK',cancelText='CANCEL',danger=false}={}){return new Promise(resolve=>{if(confirmResolver)closeAppConfirm(false);confirmResolver=resolve;$('confirmTitle').textContent=title;$('confirmMessage').textContent=message;$('confirmOkBtn').textContent=confirmText;$('confirmCancelBtn').textContent=cancelText;$('confirmIcon').textContent=danger?'!':'?';$('confirmModal').classList.toggle('danger',!!danger);$('confirmModal').classList.add('show');$('confirmModal').setAttribute('aria-hidden','false');document.body.classList.add('confirm-open');setTimeout(()=>$('confirmOkBtn').focus(),30)})}

function openDrawer(){$('overlay').classList.add('show');$('drawer').classList.add('open')}
function closeDrawer(){$('overlay').classList.remove('show');$('drawer').classList.remove('open')}
function nav(page){state.page=page;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+page));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));document.querySelectorAll('.drawer-item[data-nav]').forEach(b=>b.classList.toggle('selected',b.dataset.nav===page));closeDrawer();$('profileMenu').classList.remove('show');window.scrollTo(0,0);render()}
function currentFees(){return state.fees.filter(f=>f.month===state.month)}
function totals(fees=currentFees()){const total=fees.reduce((x,f)=>x+Number(f.amount||0),0);const paid=fees.filter(f=>f.status==='Paid').reduce((x,f)=>x+Number(f.amount||0),0);return{fees,total,paid,pending:Math.max(0,total-paid),rate:total?Math.round(paid/total*100):0}}
function dueDateForFee(f){if(f?.dueDate)return f.dueDate;const d=Math.min(28,Math.max(1,Number(state.settings.dueDay||10)));return f?.month?`${f.month}-${pad2(d)}`:''}
function isOverdue(f){return f?.status!=='Paid' && !!dueDateForFee(f) && dueDateForFee(f)<isoToday()}
function overdueTotal(){return currentFees().filter(isOverdue).reduce((n,f)=>n+Number(f.amount||0),0)}
function renderProfile(){const n=state.user?.displayName||state.user?.email?.split('@')[0]||'Coach';$('profileBtn').textContent=initials(n).slice(0,1);$('drawerAvatar').textContent=initials(n).slice(0,1);$('drawerName').textContent=n;$('drawerEmail').textContent=state.user?.email||''}
function renderDashboard(){const t=totals();$('dashStudents').textContent=state.students.length;$('dashCollected').textContent=money(t.paid);$('dashPending').textContent=money(t.pending);$('dashDue').textContent=money(overdueTotal());const recent=state.students.slice(0,3);const box=$('recentStudents');box.classList.toggle('empty',!recent.length);box.classList.toggle('recent-list',!!recent.length);box.innerHTML=recent.length?recent.map(s=>`<div class="recent-row"><div class="student-avatar recent-avatar">${initials(s.name)}</div><div class="recent-copy"><strong>${escapeHtml(s.name)}</strong><div class="recent-meta">${escapeHtml(s.className||'—')} • ${escapeHtml(s.batch||'—')}</div></div><div class="recent-fee">${money(s.feeNet)}</div></div>`).join(''):'No recent students'}
function renderStudents(){const q=($('studentSearch').value||'').toLowerCase().trim();const list=state.students.filter(s=>[s.name,s.father,s.phone,s.className,s.batch,(s.subjects||[]).join(' ')].join(' ').toLowerCase().includes(q));$('studentsList').innerHTML=list.length?list.map(s=>`<article class="student-card"><button class="student-main-hit" type="button" data-student-profile="${s.id}"><div class="student-avatar">${initials(s.name)}</div><div class="student-main-copy"><div class="student-name">${escapeHtml(s.name)}</div><div class="student-meta">${escapeHtml(s.father||'')} ${s.phone?`• ${escapeHtml(s.phone)}`:''}</div><div class="badges"><span class="badge">${escapeHtml(s.className||'Class —')}</span><span class="badge green">${escapeHtml(s.batch||'Batch —')}</span></div></div></button><div class="student-side"><div class="student-fee">${money(s.feeNet)}</div><button class="student-view-btn" type="button" onclick="window.mmtAction('profile','${s.id}')"><span class="btn-icon-3d">›</span><span>VIEW</span></button><div class="actions"><button class="action-btn wa" onclick="window.mmtAction('wa','${s.id}')" title="WhatsApp"><span class="btn-icon-3d">◔</span></button><button class="action-btn call" onclick="window.mmtAction('call','${s.id}')" title="Call"><span class="btn-icon-3d">☎</span></button><button class="action-btn edit" onclick="window.mmtAction('edit','${s.id}')" title="Edit"><span class="btn-icon-3d">✎</span></button></div></div></article>`).join(''):`<div class="list-card empty">No students found</div>`}
function formatDateIN(value){if(!value)return '—';const d=new Date(value+'T00:00:00');return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric'}).format(d)}
function attendanceForStudent(studentId,month=state.month){let present=0,absent=0,dates=0;state.attendance.filter(x=>String(x.date||'').slice(0,7)===month).forEach(day=>{const v=day.records?.[studentId];if(v==='Present'){present++;dates++}else if(v==='Absent'){absent++;dates++}});return{present,absent,marked:dates,rate:dates?Math.round(present/dates*100):0}}
function feeForStudent(studentId,month=state.month){return state.fees.find(f=>f.studentId===studentId&&f.month===month)||null}
function recentFeeRows(studentId){return state.fees.filter(f=>f.studentId===studentId).sort((a,b)=>String(b.month||'').localeCompare(String(a.month||''))).slice(0,5)}
function openStudentProfile(id){const s=state.students.find(x=>x.id===id);if(!s)return;state.profileId=id;const fee=feeForStudent(id);const a=attendanceForStudent(id);$('profileAvatar').textContent=initials(s.name);$('profileStudentName').textContent=s.name;$('profileStudentMeta').textContent=`${s.className||'Class —'} • ${s.batch||'Batch —'}`;$('profileBody').innerHTML=`<div class="profile-grid"><div class="profile-info-card"><span>Father / Guardian</span><strong>${escapeHtml(s.father||'—')}</strong></div><div class="profile-info-card"><span>Phone</span><strong>${escapeHtml(s.phone||'—')}</strong></div><div class="profile-info-card profile-wide"><span>Address</span><strong>${escapeHtml(s.address||'—')}</strong></div><div class="profile-info-card"><span>Admission Date</span><strong>${escapeHtml(formatDateIN(s.admissionDate))}</strong></div><div class="profile-info-card"><span>Subjects</span><strong>${escapeHtml((s.subjects||[]).join(', ')||'—')}</strong></div></div><div class="profile-section"><div class="section-title-row"><h3>Current Month Fee</h3><span class="status-pill ${fee?.status==='Paid'?'profile-paid':'profile-pending'}">${escapeHtml(fee?.status||'NOT GENERATED')}</span></div><div class="profile-money-row"><strong>${money(fee?.amount??s.feeNet)}</strong><span>${fee?.status==='Paid'?`Paid on ${escapeHtml((fee.paymentDate||'').slice(0,10)||'—')}`:`Due ${escapeHtml(dueDateForFee(fee)||'—')}`}</span></div></div><div class="profile-section"><div class="section-title-row"><h3>Attendance — ${escapeHtml(monthName(state.month))}</h3><strong class="profile-rate">${a.rate}%</strong></div><div class="profile-att-grid"><div><b>${a.present}</b><span>Present</span></div><div><b>${a.absent}</b><span>Absent</span></div><div><b>${a.marked}</b><span>Marked Days</span></div></div></div><div class="profile-section"><div class="section-title-row"><h3>Recent Fee History</h3><span class="count-badge">${recentFeeRows(id).length}</span></div><div class="profile-fee-list">${recentFeeRows(id).map(f=>`<div class="profile-fee-row"><div><strong>${escapeHtml(monthName(f.month||''))}</strong><small>${escapeHtml(f.paymentMode||f.status||'—')} ${f.paymentDate?`• ${escapeHtml((f.paymentDate||'').slice(0,10))}`:''}</small></div><strong>${money(f.amount)}</strong></div>`).join('')||'<div class="muted-empty">No fee records yet.</div>'}</div></div>`;$('profileModal').classList.add('show')}
function closeStudentProfile(){state.profileId=null;$('profileModal').classList.remove('show')}
function openIdCard(id){const s=state.students.find(x=>x.id===id);if(!s)return;state.idCardStudentId=id;$('idCardInstitute').textContent=state.user?.displayName||'EZEE VISION';$('idCardAvatar').textContent=initials(s.name);$('idCardName').textContent=s.name;$('idCardClass').textContent=s.className||'—';$('idCardBatch').textContent=s.batch||'—';$('idCardPhone').textContent=s.phone||'—';$('idCardAdmission').textContent=formatDateIN(s.admissionDate);$('idCardSubjects').textContent=(s.subjects||[]).join(' • ')||'—';$('idCardModal').classList.add('show')}
function closeIdCard(){state.idCardStudentId=null;$('idCardModal').classList.remove('show')}
function printIdCard(){const id=state.idCardStudentId,s=state.students.find(x=>x.id===id);if(!s)return;const institute=state.user?.displayName||'EZEE VISION';const popup=window.open('','_blank');if(!popup){toast('Please allow pop-ups to print the ID card.');return}popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Student ID Card - ${escapeHtml(s.name)}</title><style>@page{size:A4;margin:18mm}body{font-family:Arial,sans-serif;background:#fff;color:#222}.id{width:86mm;height:54mm;margin:35mm auto 0;border:1px solid #d8d4ee;border-radius:14px;overflow:hidden;box-shadow:0 4px 18px rgba(0,0,0,.08)}.head{background:linear-gradient(90deg,#4233d7,#5848e7);color:#fff;padding:12px 14px}.head b{display:block;font-size:17px}.head span{font-size:9px;opacity:.9}.body{padding:12px}.row{display:flex;gap:11px}.avatar{width:52px;height:52px;border-radius:50%;background:#eee9ff;display:grid;place-items:center;font-size:18px;font-weight:800;color:#4637d8;flex:none}.name{font-size:16px;font-weight:800;margin-bottom:2px}.meta{font-size:9px;color:#666;margin-top:3px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:10px}.box{border:1px solid #ebe7f0;border-radius:7px;padding:6px}.box small{display:block;color:#888;font-size:7px}.box strong{font-size:8px}.foot{padding:0 12px 10px;color:#888;font-size:7px;display:flex;justify-content:space-between}</style></head><body><div class="id"><div class="head"><b>${escapeHtml(institute)}</b><span>STUDENT IDENTITY CARD</span></div><div class="body"><div class="row"><div class="avatar">${initials(s.name)}</div><div><div class="name">${escapeHtml(s.name)}</div><div class="meta">${escapeHtml(s.father||'')}</div><div class="meta">${escapeHtml(s.className||'—')} • ${escapeHtml(s.batch||'—')}</div></div></div><div class="grid"><div class="box"><small>PHONE</small><strong>${escapeHtml(s.phone||'—')}</strong></div><div class="box"><small>ADMISSION</small><strong>${escapeHtml(formatDateIN(s.admissionDate))}</strong></div><div class="box" style="grid-column:1/-1"><small>SUBJECTS</small><strong>${escapeHtml((s.subjects||[]).join(' • ')||'—')}</strong></div></div></div><div class="foot"><span>Keep this card with you</span><span>FEE MANAGER</span></div></div><script>window.onload=()=>window.print();</script></body></html>`);popup.document.close()}
function openAttendanceReport(){state.attendanceReportMonth=state.attendanceReportMonth||state.month;$('attendanceReportMonth').value=state.attendanceReportMonth;$('attendanceReportModal').classList.add('show');renderAttendanceReport()}
function closeAttendanceReport(){$('attendanceReportModal').classList.remove('show')}
function buildAttendanceReportRows(){const month=$('attendanceReportMonth')?.value||state.month,cls=$('attendanceReportClass')?.value||'All',batch=$('attendanceReportBatch')?.value||'All';return state.students.filter(s=>(cls==='All'||s.className===cls)&&(batch==='All'||s.batch===batch)).map(s=>{const a=attendanceForStudent(s.id,month);return{s,a}}).sort((x,y)=>x.s.name.localeCompare(y.s.name))}
function renderAttendanceReport(){if(!$('attendanceReportList'))return;state.attendanceReportMonth=$('attendanceReportMonth').value||state.month;fillSelect($('attendanceReportClass'),uniqueValues('className'));fillSelect($('attendanceReportBatch'),uniqueValues('batch'));const rows=buildAttendanceReportRows();const marked=rows.reduce((n,x)=>n+x.a.marked,0),present=rows.reduce((n,x)=>n+x.a.present,0),absent=rows.reduce((n,x)=>n+x.a.absent,0);$('attendanceReportPresent').textContent=present;$('attendanceReportAbsent').textContent=absent;$('attendanceReportRate').textContent=(marked?Math.round(present/marked*100):0)+'%';$('attendanceReportCount').textContent=String(rows.length);$('attendanceReportList').innerHTML=rows.length?rows.map(({s,a})=>`<div class="attendance-report-row"><div><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(s.className||'')} • ${escapeHtml(s.batch||'')}</small></div><div class="attendance-report-stats"><span>${a.present} P</span><span>${a.absent} A</span><strong>${a.rate}%</strong></div></div>`).join(''):'<div class="muted-empty">No students match these filters.</div>'}
function exportAttendanceCsv(){const rows=buildAttendanceReportRows();if(!rows.length){toast('No attendance data to export.');return}const month=$('attendanceReportMonth').value||state.month;const lines=[['Student Name','Class','Batch','Present','Absent','Marked Days','Attendance %'].map(csvEscape).join(',')];rows.forEach(({s,a})=>lines.push([s.name,s.className,s.batch,a.present,a.absent,a.marked,a.rate+'%'].map(csvEscape).join(',')));const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`FEE-MANAGER-Attendance-${month}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Attendance CSV exported.')}
function printAttendanceReport(){const rows=buildAttendanceReportRows();if(!rows.length){toast('No attendance data to print.');return}const month=$('attendanceReportMonth').value||state.month;const popup=window.open('','_blank');if(!popup){toast('Please allow pop-ups to print attendance.');return}popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Attendance Report ${escapeHtml(monthName(month))}</title><style>@page{size:A4;margin:14mm}body{font-family:Arial,sans-serif;color:#222}h1{margin:0 0 3px;font-size:22px}p{margin:0 0 14px;color:#666}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #ddd;padding:7px;text-align:left}th{background:#f2f0fb}.right{text-align:right}.foot{margin-top:16px;color:#777;font-size:10px}</style></head><body><h1>EZEE VISION</h1><p>Monthly Attendance Report • ${escapeHtml(monthName(month))}</p><table><thead><tr><th>Student</th><th>Class</th><th>Batch</th><th>Present</th><th>Absent</th><th>Marked</th><th class="right">Rate</th></tr></thead><tbody>${rows.map(({s,a})=>`<tr><td>${escapeHtml(s.name)}</td><td>${escapeHtml(s.className||'—')}</td><td>${escapeHtml(s.batch||'—')}</td><td>${a.present}</td><td>${a.absent}</td><td>${a.marked}</td><td class="right">${a.rate}%</td></tr>`).join('')}</tbody></table><div class="foot">Computer generated from FEE MANAGER.</div><script>window.onload=()=>window.print();</script></body></html>`);popup.document.close()}
function lastMonths(count=6){const d=new Date(`${state.month}-01T00:00:00`);const arr=[];for(let i=count-1;i>=0;i--){const x=new Date(d.getFullYear(),d.getMonth()-i,1);arr.push(`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}`)}return arr}
function renderAnalytics(){const months=lastMonths(6);const rows=months.map(m=>{const fees=state.fees.filter(f=>f.month===m);const collected=fees.filter(f=>f.status==='Paid').reduce((n,f)=>n+Number(f.amount||0),0);const total=fees.reduce((n,f)=>n+Number(f.amount||0),0);const expenses=state.expenses.filter(x=>(x.date||'').slice(0,7)===m).reduce((n,x)=>n+Number(x.amount||0),0);return{m,total,collected,expenses,net:collected-expenses,rate:total?Math.round(collected/total*100):0}});const max=Math.max(1,...rows.map(x=>Math.max(x.collected,x.expenses)));const cur=rows.at(-1)||{collected:0,expenses:0,net:0,rate:0};$('analyticsCollected').textContent=money(cur.collected);$('analyticsExpenses').textContent=money(cur.expenses);$('analyticsNet').textContent=money(cur.net);$('analyticsRate').textContent=cur.rate+'%';$('analyticsRows').innerHTML=rows.map(x=>`<div class="analytics-row"><div class="analytics-month">${escapeHtml(monthName(x.m))}</div><div class="analytics-bars"><span class="bar fee" style="width:${Math.round(x.collected/max*100)}%"></span><span class="bar exp" style="width:${Math.round(x.expenses/max*100)}%"></span></div><div class="analytics-values"><b>${money(x.collected)}</b><span>Exp ${money(x.expenses)}</span></div></div>`).join('');$('analyticsLegend').innerHTML='<span><i class="legend-dot fee"></i>Collected</span><span><i class="legend-dot exp"></i>Expenses</span>'}
function uniqueValues(field){return [...new Set(state.students.map(s=>s[field]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}))}
function fillSelect(el,values){if(!el)return;const previous=el.value;el.innerHTML='<option>All</option>'+values.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');if(values.includes(previous))el.value=previous}
function renderFilters(){fillSelect($('classFilter'),uniqueValues('className'));fillSelect($('batchFilter'),uniqueValues('batch'));fillSelect($('reportClassFilter'),uniqueValues('className'));fillSelect($('reportBatchFilter'),uniqueValues('batch'))}
function filteredFeeRows(){const fees=currentFees();const cls=$('reportClassFilter')?.value||'All',batch=$('reportBatchFilter')?.value||'All',q=($('reportSearch')?.value||'').trim().toLowerCase();return fees.map(f=>({f,s:state.students.find(s=>s.id===f.studentId)})).filter(x=>x.s).filter(({s})=>cls==='All'||s.className===cls).filter(({s})=>batch==='All'||s.batch===batch).filter(({s})=>!q||[s.name,s.father,s.phone,s.className,s.batch,(s.subjects||[]).join(' ')].join(' ').toLowerCase().includes(q))}
function renderPayments(){const {fees}=totals();const status=$('statusFilter').value,cls=$('classFilter').value,batch=$('batchFilter').value;const paid=fees.filter(f=>f.status==='Paid').length,pending=fees.length-paid;$('paidCountChip').textContent=`✓ ${paid} Paid`;$('pendingCountChip').textContent=`! ${pending} Pending`;let list=fees.map(f=>({f,s:state.students.find(s=>s.id===f.studentId)})).filter(x=>x.s);if(status!=='All')list=list.filter(x=>x.f.status===status);if(cls!=='All')list=list.filter(x=>x.s.className===cls);if(batch!=='All')list=list.filter(x=>x.s.batch===batch);$('paymentsList').innerHTML=list.length?list.map(({f,s})=>{const overdue=isOverdue(f);return `<article class="payment-card ${f.status==='Paid'?'paid':''} ${overdue?'overdue':''}"><div class="payment-top"><div class="payment-main"><div class="student-avatar" style="width:50px;height:50px;font-size:18px">${initials(s.name)}</div><div><div class="payment-name">${escapeHtml(s.name)}</div><div class="payment-date">📅 ${escapeHtml(monthName(state.month))}</div>${f.status==='Paid'?`<div class="payment-date">Paid on ${escapeHtml((f.paymentDate||'').slice(0,10))}</div>`:`<div class="payment-date ${overdue?'overdue-text':''}">Due ${escapeHtml(dueDateForFee(f)||'—')}${overdue?' • OVERDUE':''}</div>`}</div></div><div style="text-align:right"><div class="payment-amount">${money(f.amount)}</div><span class="status-pill">${f.status.toUpperCase()}</span></div></div><div class="payment-actions">${f.status==='Paid'?`<button class="small-primary" onclick="window.mmtAction('receipt','${f.id}')"><span class="btn-icon-3d">▤</span><span>SEND RECEIPT</span></button><button class="outline-btn" onclick="window.mmtAction('revert','${f.id}')"><span class="btn-icon-3d">↶</span><span>REVERT</span></button>`:`<button class="small-primary" onclick="window.mmtAction('paid','${f.id}')"><span class="btn-icon-3d">✓</span><span>MARK PAID</span></button><button class="outline-btn" onclick="window.mmtAction('remind','${f.id}')"><span class="btn-icon-3d">!</span><span>REMIND</span></button>`}</div></article>`}).join(''):`<div class="list-card empty">No fee records</div>`}
function renderReports(){const rows=filteredFeeRows();const rawRows=currentFees();const t=totals(rawRows);$('reportTotal').textContent=money(t.total);$('reportCollected').textContent=money(t.paid);$('reportPending').textContent=money(t.pending);$('reportRate').textContent=t.rate+'%';$('rateBar').style.width=t.rate+'%';$('reportStudentCount').textContent=state.students.length;$('reportActiveCount').textContent=state.students.filter(s=>s.status!=='Inactive').length;$('reportPendingCount').textContent=rawRows.filter(f=>f.status!=='Paid').length;$('reportOverdueCount').textContent=money(overdueTotal());const p=rows.filter(({f})=>f.status!=='Paid');$('pendingReportList').innerHTML=p.length?p.map(({f,s})=>`<div class="report-pending-row"><div class="student-avatar" style="width:44px;height:44px;font-size:15px">${initials(s.name)}</div><div><strong>${escapeHtml(s.name)}</strong><div class="student-meta">${escapeHtml(s.className||'')} ${s.batch?`• ${escapeHtml(s.batch)}`:''}</div><div class="student-meta ${isOverdue(f)?'overdue-text':''}">Due ${escapeHtml(dueDateForFee(f)||'—')}${isOverdue(f)?' • OVERDUE':''}</div></div><strong class="pending-amount">${money(f.amount)}</strong></div>`).join(''):'<div class="muted-empty">No pending fees in this filter.</div>';$('reportLedgerCount').textContent=`${rows.length} record${rows.length===1?'':'s'}`;const ledger=$('reportLedgerList');ledger.innerHTML=rows.length?rows.map(({f,s})=>`<div class="ledger-row"><div class="ledger-main"><div class="student-avatar" style="width:42px;height:42px;font-size:14px">${initials(s.name)}</div><div><strong>${escapeHtml(s.name)}</strong><div class="student-meta">${escapeHtml(s.className||'—')} • ${escapeHtml(s.batch||'—')}</div></div></div><div class="ledger-status ${f.status==='Paid'?'is-paid':'is-pending'}"><strong>${money(f.amount)}</strong><span>${escapeHtml(f.status)}</span></div></div>`).join(''):'<div class="muted-empty">No fee records match the selected filters.</div>';const modeCounts={};rawRows.filter(f=>f.status==='Paid').forEach(f=>{const mode=f.paymentMode||'Cash';modeCounts[mode]=(modeCounts[mode]||0)+Number(f.amount||0)});const modes=Object.entries(modeCounts).sort((a,b)=>b[1]-a[1]);$('paymentModeList').innerHTML=modes.length?modes.map(([mode,amount])=>`<div class="report-line"><span>${escapeHtml(mode)}</span><strong>${money(amount)}</strong></div>`).join(''):'<div class="muted-empty">No paid payments in this month.</div>'}
function attendanceRecords(){return state.attendance.find(x=>x.date===state.attendanceDate&&x.className===($('attendanceClassFilter')?.value||'All')&&x.batch===($('attendanceBatchFilter')?.value||'All'))?.records||{}}
function attendanceFilteredStudents(){const cls=$('attendanceClassFilter')?.value||'All',batch=$('attendanceBatchFilter')?.value||'All';return state.students.filter(s=>(cls==='All'||s.className===cls)&&(batch==='All'||s.batch===batch))}
function renderAttendance(){if(!$('attendanceList'))return;const cls=$('attendanceClassFilter').value||'All',batch=$('attendanceBatchFilter').value||'All';$('attendanceDateLabel').textContent=new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(state.attendanceDate+'T00:00:00'));$('attendanceDateBtn').textContent=$('attendanceDateLabel').textContent+' ▾';const students=attendanceFilteredStudents();const rec=attendanceRecords();let present=0,absent=0;students.forEach(s=>rec[s.id]==='Present'?present++:rec[s.id]==='Absent'?absent++:0);$('attendancePresent').textContent=present;$('attendanceAbsent').textContent=absent;$('attendanceRate').textContent=(present+absent?Math.round(present/(present+absent)*100):0)+'%';$('attendanceList').innerHTML=students.length?students.map(s=>{const v=rec[s.id]||'';return `<div class="attendance-row"><div><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(s.className||'')} • ${escapeHtml(s.batch||'')}</small></div><div class="attendance-actions"><button class="att-btn ${v==='Present'?'active-present':''}" data-att="${s.id}" data-value="Present"><span class="btn-icon-3d">P</span></button><button class="att-btn ${v==='Absent'?'active-absent':''}" data-att="${s.id}" data-value="Absent"><span class="btn-icon-3d">A</span></button></div></div>`}).join(''):'<div class="list-card empty">No students match the selected class/batch.</div>'}
function renderExpenses(){if(!$('expenseList'))return;const ym=state.month,today=isoToday();const monthTotal=state.expenses.filter(x=>(x.date||'').slice(0,7)===ym).reduce((n,x)=>n+Number(x.amount||0),0);const todayTotal=state.expenses.filter(x=>x.date===today).reduce((n,x)=>n+Number(x.amount||0),0);const collected=totals().paid;$('expenseMonthTotal').textContent=money(monthTotal);$('expenseTodayTotal').textContent=money(todayTotal);$('expenseNetTotal').textContent=money(collected-monthTotal);$('expenseCount').textContent=String(state.expenses.filter(x=>(x.date||'').slice(0,7)===ym).length);const list=state.expenses.filter(x=>(x.date||'').slice(0,7)===ym);$('expenseList').innerHTML=list.length?list.map(x=>`<div class="expense-row"><div><strong>${escapeHtml(x.title)}</strong><small>${escapeHtml(x.category||'Other')} • ${escapeHtml(x.date||'')}</small>${x.note?`<small>${escapeHtml(x.note)}</small>`:''}</div><div><strong>${money(x.amount)}</strong><button class="text-btn danger-text" data-expense-delete="${x.id}">Delete</button></div></div>`).join(''):'<div class="muted-empty">No expenses recorded this month.</div>'}
function render(){document.querySelectorAll('#currentMonthLabel,#paymentMonthLabel,#reportMonthLabel').forEach(el=>el.textContent=monthName(state.month));$('reportMonthBtn').textContent=monthName(state.month)+' ▾';renderProfile();renderStudentModalOptions();renderDashboard();renderStudents();renderFilters();renderPayments();renderReports();renderAttendance();renderExpenses();renderAnalytics()}
function renderStudentModalOptions(){const classEl=$('sClass'),batchEl=$('sBatch'),subEl=$('sSubject');if(!classEl)return;const selectedClass=classEl.value,selectedBatch=batchEl.value,selectedSubs=[...subEl.selectedOptions].map(o=>o.value);classEl.innerHTML='<option value="">Class (tap to select)</option>'+state.settings.classes.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');batchEl.innerHTML='<option value="">Batch (tap to select)</option>'+state.settings.batches.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');subEl.innerHTML=state.settings.subjects.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');if(state.settings.classes.includes(selectedClass))classEl.value=selectedClass;if(state.settings.batches.includes(selectedBatch))batchEl.value=selectedBatch;[...subEl.options].forEach(o=>o.selected=selectedSubs.includes(o.value))}
function openStudentModal(id=null){state.editingId=id;const s=state.students.find(x=>x.id===id);$('studentModalTitle').textContent=s?'Edit Student':'Add Student';$('deleteStudentBtn').hidden=!s;$('saveStudentBtn').textContent=s?'UPDATE STUDENT':'SAVE STUDENT';$('sName').value=s?.name||'';$('sFather').value=s?.father||'';$('sPhone').value=s?.phone||'';$('sAddress').value=s?.address||'';$('sClass').value=s?.className||'';$('sBatch').value=s?.batch||'';[...$('sSubject').options].forEach(o=>o.selected=s?.subjects?.includes(o.value));$('sDate').value=s?.admissionDate||isoToday();$('sFee').value=s?.fee??1500;$('sDiscount').value=s?.discount??0;$('sDiscountReason').value=s?.discountReason||'';$('studentModal').classList.add('show')}
function closeStudent(){$('studentModal').classList.remove('show')}
function openPaymentModal(id){const f=state.fees.find(x=>x.id===id);if(!f)return;state.payingId=id;$('paymentAmount').value=f.amount||0;$('paymentDate').value=isoToday();$('paymentMode').value=f.paymentMode||'Cash';$('paymentNote').value=f.paymentNote||'';$('paymentModal').classList.add('show')}
function closePayment(){state.payingId=null;$('paymentModal').classList.remove('show')}
function nextReceiptNo(){const prefix=`EV-${state.month.replace('-','')}-`;const nums=state.fees.map(f=>String(f.receiptNo||'')).filter(x=>x.startsWith(prefix)).map(x=>Number(x.slice(prefix.length))).filter(Number.isFinite);return `${prefix}${String((nums.length?Math.max(...nums):0)+1).padStart(4,'0')}`}
function numberToWordsINR(n){const ones=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];const tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];const under100=n=>n<20?ones[n]:tens[Math.floor(n/10)]+(n%10?' '+ones[n%10]:'');const under1000=n=>n<100?under100(n):ones[Math.floor(n/100)]+' Hundred'+(n%100?' '+under100(n%100):'');n=Math.floor(Number(n)||0);if(n===0)return'Zero';let out='';if(n>=10000000){out+=under1000(Math.floor(n/10000000))+' Crore ';n%=10000000}if(n>=100000){out+=under1000(Math.floor(n/100000))+' Lakh ';n%=100000}if(n>=1000){out+=under1000(Math.floor(n/1000))+' Thousand ';n%=1000}if(n>0)out+=under1000(n);return `${out.trim()} Rupees Only`}
function openReceipt(id){const f=state.fees.find(x=>x.id===id),s=state.students.find(x=>x.id===f?.studentId);if(!f||!s)return;$('receiptDate').textContent=new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric'}).format(new Date());$('receiptBody').innerHTML=`<div class="receipt-row"><span>Receipt No.</span><strong>#${escapeHtml(f.receiptNo||'—')}</strong></div><div class="receipt-row"><span>Student Name</span><strong>${escapeHtml(s.name)}</strong></div><div class="receipt-row"><span>Father's Name</span><strong>${escapeHtml(s.father||'-')}</strong></div><div class="receipt-row"><span>Class / Batch</span><strong>${escapeHtml(s.className||'-')} / ${escapeHtml(s.batch||'-')}</strong></div><div class="receipt-row"><span>Address</span><strong>${escapeHtml(s.address||'-')}</strong></div><div class="receipt-row"><span>Month / Period</span><strong>${escapeHtml(monthName(f.month||state.month))}</strong></div><div class="receipt-row"><span>Due Date</span><strong>${escapeHtml(dueDateForFee(f)||'-')}</strong></div><div class="receipt-row"><span>Payment Date</span><strong>${escapeHtml((f.paymentDate||'').slice(0,10)||'-')}</strong></div><div class="receipt-row"><span>Payment Mode</span><strong>${escapeHtml(f.paymentMode||'-')}</strong></div><div class="receipt-row"><span>Amount in Words</span><strong>${escapeHtml(numberToWordsINR(f.amount))}</strong></div>`;$('receiptAmount').textContent=money(f.amount);$('receiptModal').dataset.feeId=id;$('receiptModal').classList.add('show')}
function closeReceipt(){$('receiptModal').classList.remove('show')}
function printReceipt(){const id=$('receiptModal').dataset.feeId,f=state.fees.find(x=>x.id===id),s=state.students.find(x=>x.id===f?.studentId);if(!f||!s)return;const popup=window.open('','_blank');if(!popup){toast('Please allow pop-ups to print the receipt.');return}popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Receipt ${escapeHtml(f.receiptNo||'')}</title><style>@page{size:A4;margin:14mm}body{font-family:Arial,sans-serif;color:#222}.head{background:#4636db;color:#fff;padding:18px;border-radius:12px}.head h1{margin:0 0 3px;font-size:24px}.head p{margin:0;font-size:11px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}.row{border:1px solid #ddd;padding:9px;border-radius:8px}.row span{display:block;color:#666;font-size:10px;margin-bottom:3px}.row strong{font-size:12px}.amount{margin-top:14px;padding:14px;background:#f1efff;border:1px solid #d9d5ff;border-radius:10px;font-size:18px}.sign{display:flex;justify-content:space-between;margin-top:55px;color:#666;font-size:11px}</style></head><body><div class="head"><h1>EZEE VISION</h1><p>OFFICIAL PAYMENT RECEIPT</p></div><div class="grid"><div class="row"><span>Receipt No.</span><strong>#${escapeHtml(f.receiptNo||'-')}</strong></div><div class="row"><span>Payment Date</span><strong>${escapeHtml((f.paymentDate||'').slice(0,10)||'-')}</strong></div><div class="row"><span>Student Name</span><strong>${escapeHtml(s.name)}</strong></div><div class="row"><span>Father / Guardian</span><strong>${escapeHtml(s.father||'-')}</strong></div><div class="row"><span>Class / Batch</span><strong>${escapeHtml(s.className||'-')} / ${escapeHtml(s.batch||'-')}</strong></div><div class="row"><span>Month / Period</span><strong>${escapeHtml(monthName(f.month||state.month))}</strong></div><div class="row"><span>Payment Mode</span><strong>${escapeHtml(f.paymentMode||'-')}</strong></div><div class="row"><span>Due Date</span><strong>${escapeHtml(dueDateForFee(f)||'-')}</strong></div></div><div class="amount"><strong>AMOUNT PAID: ${escapeHtml(money(f.amount))}</strong><div style="font-size:11px;margin-top:6px">${escapeHtml(numberToWordsINR(f.amount))}</div></div><div class="sign"><span>Authorised Signature</span><span>Receiver's Signature</span></div><script>window.onload=()=>window.print();</script></body></html>`);popup.document.close()}
function sendReceiptWhatsApp(){const id=$('receiptModal').dataset.feeId,f=state.fees.find(x=>x.id===id),s=state.students.find(x=>x.id===f?.studentId);if(!f||!s||!s.phone){toast('Phone number not available.');return}const text=`Payment Receipt – EZEE VISION\n\nStudent: ${s.name}\nMonth: ${monthName(f.month||state.month)}\nAmount Paid: ${money(f.amount)}\nPayment Mode: ${f.paymentMode||'-'}\nReceipt No.: ${f.receiptNo||'-'}\nPayment Date: ${(f.paymentDate||'').slice(0,10)||'-'}\n\nThank you.`;window.open('https://wa.me/91'+s.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(text),'_blank')}
function openMonthPicker(){if(!$('monthPicker'))return;$('monthPicker').value=state.month;if(typeof $('monthPicker').showPicker==='function')$('monthPicker').showPicker();else $('monthPicker').click()}
function setMonth(value){if(!/^\d{4}-\d{2}$/.test(value))return;state.month=value;state.attendanceReportMonth=value;render();toast(`Showing ${monthName(value)}.`)}
function exportReportCsv(){const rows=filteredFeeRows();if(!rows.length){toast('No report records to export.');return}const header=['Student Name','Father / Guardian','Phone','Class','Batch','Month','Amount','Status','Due Date','Payment Date','Payment Mode','Receipt No.'];const lines=[header.map(csvEscape).join(',')];rows.forEach(({f,s})=>lines.push([s.name,s.father,s.phone,s.className,s.batch,monthName(state.month),f.amount,f.status,dueDateForFee(f),(f.paymentDate||'').slice(0,10),f.paymentMode||'',f.receiptNo||''].map(csvEscape).join(',')));const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`FEE-MANAGER-Fee-Report-${state.month}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('CSV report exported.')}
function printReport(){const rows=filteredFeeRows();if(!rows.length){toast('No report records to print.');return}const popup=window.open('', '_blank');if(!popup){toast('Please allow pop-ups to print the report.');return}const label=monthName(state.month);const total=rows.reduce((x,{f})=>x+Number(f.amount||0),0);const paid=rows.filter(({f})=>f.status==='Paid').reduce((x,{f})=>x+Number(f.amount||0),0);popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>FEE MANAGER Fee Report - ${escapeHtml(label)}</title><style>@page{size:A4;margin:16mm}body{font-family:Arial,sans-serif;color:#222}h1{margin:0 0 4px;font-size:24px}h2{margin:22px 0 8px;font-size:17px}p{margin:0 0 14px;color:#666}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}.box{border:1px solid #ddd;border-radius:10px;padding:10px}.box b{display:block;font-size:18px;margin-top:4px}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #ddd;padding:7px;text-align:left}th{background:#f4f3fb}.right{text-align:right}.paid{color:#187a4b;font-weight:700}.pending{color:#b33d43;font-weight:700}.foot{margin-top:18px;color:#777;font-size:10px}</style></head><body><h1>EZEE VISION</h1><p>Official Coaching Fee Report • ${escapeHtml(label)}</p><div class="summary"><div class="box">Total Fee<b>${escapeHtml(money(total))}</b></div><div class="box">Collected<b>${escapeHtml(money(paid))}</b></div><div class="box">Pending<b>${escapeHtml(money(Math.max(0,total-paid)))}</b></div></div><table><thead><tr><th>Student</th><th>Class</th><th>Batch</th><th>Status</th><th>Due Date</th><th class="right">Amount</th><th>Payment Date</th><th>Mode</th></tr></thead><tbody>${rows.map(({f,s})=>`<tr><td>${escapeHtml(s.name)}</td><td>${escapeHtml(s.className||'—')}</td><td>${escapeHtml(s.batch||'—')}</td><td class="${f.status==='Paid'?'paid':'pending'}">${escapeHtml(f.status)}${isOverdue(f)?' / OVERDUE':''}</td><td>${escapeHtml(dueDateForFee(f)||'—')}</td><td class="right">${escapeHtml(money(f.amount))}</td><td>${escapeHtml((f.paymentDate||'').slice(0,10)||'—')}</td><td>${escapeHtml(f.paymentMode||'—')}</td></tr>`).join('')}</tbody></table><div class="foot">Generated from FEE MANAGER. This report is computer generated.</div><script>window.onload=()=>window.print();</script></body></html>`);popup.document.close()}
async function saveSettings(patch){state.settings={...state.settings,...patch};await upsertUserProfile(state.uid,{settings:state.settings});render()}
function catalogData(type){return type==='classes'?state.settings.classes:type==='batches'?state.settings.batches:state.settings.subjects}
function openCatalogManager(type){const title=type==='classes'?'Classes':type==='batches'?'Batches':'Subjects';const items=catalogData(type);$('catalogModalTitle').textContent=title;$('catalogModalSubtitle').textContent=`Manage your ${title.toLowerCase()} in the cloud`;$('catalogType').value=type;$('catalogInput').value='';$('catalogList').innerHTML=items.map((x,i)=>`<div class="catalog-row"><span>${escapeHtml(x)}</span><button type="button" class="outline-btn mini" data-catalog-delete="${i}">DELETE</button></div>`).join('')||'<div class="muted-empty">No items yet.</div>';$('catalogModal').classList.add('show')}
function closeCatalog(){$('catalogModal').classList.remove('show')}
async function addCatalogItem(){const type=$('catalogType').value,value=$('catalogInput').value.trim();if(!value)return toast('Enter a name first.');const arr=[...catalogData(type)];if(arr.some(x=>x.toLowerCase()===value.toLowerCase()))return toast('Already exists.');arr.push(value);await saveSettings({[type]:arr});openCatalogManager(type);toast(`${value} added.`)}
async function deleteCatalogItem(index){const type=$('catalogType').value,arr=[...catalogData(type)],value=arr[index];if(!value)return;const inUse=type==='classes'?state.students.some(s=>s.className===value):type==='batches'?state.students.some(s=>s.batch===value):state.students.some(s=>(s.subjects||[]).includes(value));if(inUse)return toast(`Cannot delete ${value}; it is being used by a student.`);arr.splice(index,1);await saveSettings({[type]:arr});openCatalogManager(type);toast(`${value} deleted.`)}
function openFeeSettings(){const d=Math.min(28,Math.max(1,Number(state.settings.dueDay||10)));$('dueDayInput').value=d;$('settingsHint').textContent=`New monthly fees will use day ${d} as the due date.`;$('feeSettingsModal').classList.add('show')}
